mapper.update:
UPDATE Dept
SET pid = #{pid},
dname = #{dname},
captain = #{captain}
WHERE id = #{id}

mapper.delete:
WITH RECURSIVE SubDepts AS (
SELECT id FROM Dept WHERE id = #{deptId}
UNION ALL
SELECT d.id FROM Dept d INNER JOIN SubDepts sd ON d.pid = sd.id
)
DELETE FROM Dept WHERE id IN (SELECT id FROM SubDepts);

mapper.select:
SELECT id, pid, dname, captain
FROM Dept
WHERE id = #{deptId}
